<?php require_once __DIR__.'/alumno_common.php'; $stmt=$pdo->prepare("SELECT v.adeudo,v.concepto,v.monto,v.pagado,v.saldo,v.fecha_vencimiento,v.estatus,pe.nombre AS periodo FROM vw_saldo_adeudos v JOIN adeudos a ON a.id=v.adeudo JOIN periodos_escolares pe ON pe.id=a.id_periodo WHERE a.alumno=? ORDER BY a.fecha_vencimiento DESC");$stmt->execute([$alumnoActual['id']]);$adeudosLista=$stmt->fetchAll();$totalAdeudado=0.0;$totalPagado=0.0;foreach($adeudosLista as $a){if(!in_array($a['estatus'],['pagado','cancelado'],true))$totalAdeudado+=(float)$a['saldo'];$totalPagado+=(float)$a['pagado'];} $stmt=$pdo->prepare("SELECT p.fecha_pago,p.monto,p.metodo_pago,p.referencia,c.nombre AS concepto FROM pagos p JOIN adeudos a ON a.id=p.adeudo JOIN conceptos_pago c ON c.id=a.concepto WHERE a.alumno=? ORDER BY p.fecha_pago DESC LIMIT 20");$stmt->execute([$alumnoActual['id']]);$pagosLista=$stmt->fetchAll(); alumno_layout('Pagos y adeudos','Consulta tus saldos, vencimientos y pagos registrados','pagosAdeudos.html',compact('adeudosLista','pagosLista','totalAdeudado','totalPagado'));
